package com.luizotavio.academia.controller;
import com.luizotavio.academia.entity.*; import com.luizotavio.academia.repository.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/alunos") public class AlunoController { private final AlunoRepository repo; public AlunoController(AlunoRepository r){repo=r;} @GetMapping public List<Aluno> listar(){return repo.findAll();} @GetMapping("/{id}") public ResponseEntity<Aluno> buscar(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @PostMapping public ResponseEntity<Aluno> criar(@Valid @RequestBody Aluno a){return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(a));} @PutMapping("/{id}") public ResponseEntity<Aluno> atualizar(@PathVariable Long id,@Valid @RequestBody Aluno a){return repo.findById(id).map(x->{x.setNome(a.getNome());x.setEmail(a.getEmail());x.setTelefone(a.getTelefone());x.setDataNascimento(a.getDataNascimento());return ResponseEntity.ok(repo.save(x));}).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<Void> excluir(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();} }
